import React, { useEffect, useState } from 'react';
import axios from 'axios';

interface Event {
  id: number;
  email_id: number;
  recipient: string;
  event_type: string;
  timestamp: string;
}

const RecentActivityTable: React.FC = () => {
  const [events, setEvents] = useState<Event[]>([]);

  useEffect(() => {
    // Mock data for demo
    setEvents([
      { id: 1, email_id: 1, recipient: 'user1@example.com', event_type: 'opened', timestamp: '2026-03-06T10:00:00Z' },
      { id: 2, email_id: 2, recipient: 'user2@example.com', event_type: 'clicked', timestamp: '2026-03-06T09:30:00Z' },
      { id: 3, email_id: 3, recipient: 'user3@example.com', event_type: 'sent', timestamp: '2026-03-06T09:00:00Z' }
    ]);
    // Uncomment for real API
    // axios.get('/api/dashboard/recent-events').then(res => setEvents(res.data));
  }, []);

  return (
    <div>
      <h3>Recent Activity</h3>
      <table>
        <thead>
          <tr>
            <th>Recipient</th>
            <th>Event</th>
            <th>Timestamp</th>
          </tr>
        </thead>
        <tbody>
          {events.map(event => (
            <tr key={event.id}>
              <td>{event.recipient}</td>
              <td>{event.event_type}</td>
              <td>{new Date(event.timestamp).toLocaleString()}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default RecentActivityTable;
